{
  "info": {
    "title": "UAE Payment API",
    "description": "## UAE Open Finance Payment API Specification",
    "version": "v2.2-rc2"
  },
  "servers": [
    {
      "url": "https://rs1.[LFICODE].apihub.openfinance.ae/open-finance/payment/v2.1"
    },
    {
      "url": "https://rs1.[LFICODE].preprod.apihub.openfinance.ae/open-finance/payment/v2.1"
    },
    {
      "url": "https://rs1.altareq1.sandbox.apihub.openfinance.ae/open-finance/payment/v2.1"
    }
  ],
  "source_path": "/payment-consents",
  "operations": {
    "get": {
      "tags": [
        "Consent"
      ],
      "summary": "Retrieve Linked Payment Consents",
      "description": "Retrieve all Payment Consents linked by a given `BaseConsentId`, as part of a linked consent group.",
      "operationId": "RetrievePaymentConsentsByBaseConsentId",
      "parameters": [
        {
          "$ref": "#/components/parameters/authorization"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id-request"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        },
        {
          "$ref": "#/components/parameters/baseConsentId"
        }
      ],
      "responses": {
        "200": {
          "$ref": "#/components/responses/200BaseConsentIdConsentsRetrieve"
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "404": {
          "$ref": "#/components/responses/404Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "415": {
          "$ref": "#/components/responses/415Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "security": [
        {
          "TPPOAuth2Security": [
            "openid",
            "payments"
          ]
        }
      ]
    }
  }
}

{
  "in": "header",
  "name": "authorization",
  "required": true,
  "description": "An authorization Token as per https://tools.ietf.org/html/rfc6750",
  "schema": {
    "type": "string"
  },
  "example": "Bearer 12773da5-81c5-45e7-893c-381ca3cecc30"
}

{
  "in": "header",
  "name": "x-fapi-auth-date",
  "required": false,
  "description": "The time when the User last logged in with the TPP. \nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below: \nSun, 10 Sep 2023 19:43:31 UTC",
  "schema": {
    "type": "string",
    "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\d{4} \\d{2}:\\d{2}:\\d{2} (GMT|UTC)$"
  },
  "example": "Thu, 26 Jan 2023 16:31:32 UTC"
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": false,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  },
  "example": "51.235.115.203"
}

{
  "in": "header",
  "name": "x-fapi-interaction-id",
  "required": false,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  },
  "example": "49df2c2c-6b80-40ee-96a1-71910a248048"
}

{
  "in": "header",
  "name": "x-customer-user-agent",
  "description": "Indicates the user-agent that the User is using.",
  "required": false,
  "schema": {
    "type": "string"
  },
  "example": "Mozilla/5.0 (iPhone; CPU iPhone OS 10_3_1 like Mac OS X) AppleWebKit/603.1.30 (KHTML, like Gecko) Version/10.0 Mobile/14E304 Safari/602.1"
}

{
  "in": "query",
  "name": "baseConsentId",
  "required": false,
  "description": "A Base Consent ID value that defines a group of linked consents. This parameter **must not** be supplied if `combinedConsentGroupId` parameter is supplied.",
  "schema": {
    "type": "string"
  },
  "allowEmptyValue": false,
  "example": "abc-19877d98-ab0e-4758-92a7-vvffr1234abv"
}

{
  "description": "Retrieve Payment Consents by BaseConsentId",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  },
  "content": {
    "application/jwt": {
      "schema": {
        "$ref": "#/components/schemas/AEPaymentConsentsByBaseConsentIdResponseSigned"
      }
    }
  }
}

{
  "required": true,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  },
  "example": "49df2c2c-6b80-40ee-96a1-71910a248048"
}

{
  "description": "Payment Consents By BaseConsentId Response Signed Schema\n",
  "allOf": [
    {
      "$ref": "#/components/schemas/AEJwt"
    },
    {
      "type": "object",
      "properties": {
        "message": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBankServiceInitiationConsentStatusV21.AEBankServiceInitiationConsentProperties"
          }
        }
      },
      "required": [
        "message"
      ]
    }
  ]
}

{
  "description": "[https://www.rfc-editor.org/rfc/rfc7519](https://www.rfc-editor.org/rfc/rfc7519)\n",
  "type": "object",
  "properties": {
    "iss": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1)\n",
      "type": "string"
    },
    "exp": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4)\n",
      "type": "number"
    },
    "nbf": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)\n",
      "type": "number"
    },
    "aud": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3)\n",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "iat": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6)\n",
      "type": "number"
    }
  },
  "required": [
    "iss",
    "exp",
    "nbf"
  ]
}

{
  "type": "object",
  "required": [
    "Data",
    "Links"
  ],
  "properties": {
    "Data": {
      "type": "object",
      "properties": {
        "ConsentId": {
          "$ref": "#/components/schemas/AEPushedAuthorizationRequests.AEConsentId"
        },
        "BaseConsentId": {
          "$ref": "#/components/schemas/AEPushedAuthorizationRequests.AEBaseConsentId"
        },
        "IsSingleAuthorization": {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.IsSingleAuthorization"
        },
        "AuthorizationExpirationDateTime": {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AuthorizationExpirationDateTime"
        },
        "Permissions": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationConsentPermissionCodes"
          },
          "description": "Permission codes granted by the User to the TPP, allowing the TPP to check execute a balance check."
        },
        "ExpirationDateTime": {
          "$ref": "#/components/schemas/AEPushedAuthorizationRequests.AEConsentExpirationDateTime"
        },
        "Status": {
          "$ref": "#/components/schemas/AEConsentStatus.AEConsentStatusCodes"
        },
        "RevokedBy": {
          "$ref": "#/components/schemas/AEConsentStatus.AERevokedByCodes"
        },
        "CreationDateTime": {
          "$ref": "#/components/schemas/AEConsentStatus.AECreationDateTime"
        },
        "StatusUpdateDateTime": {
          "$ref": "#/components/schemas/AEConsentStatus.AEStatusUpdateDateTime"
        },
        "Charges": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBankServiceInitiation.AECharges"
          },
          "minItems": 1
        },
        "ExchangeRate": {
          "$ref": "#/components/schemas/AEConsentStatus.AEExchangeRateInformation"
        },
        "CurrencyRequest": {
          "$ref": "#/components/schemas/AEBankServiceInitiation.AECurrencyRequest"
        },
        "ControlParameters": {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequestsV21.AEBankServiceInitiationControlParametersProperties"
        },
        "DebtorReference": {
          "$ref": "#/components/schemas/AEBankServiceInitiation.AEDebtorReference"
        },
        "CreditorReference": {
          "$ref": "#/components/schemas/AEBankServiceInitiation.AECreditorReference"
        },
        "PaymentPurposeCode": {
          "$ref": "#/components/schemas/AEBankServiceInitiation.AEPaymentPurposeCode"
        },
        "SponsoredTPPInformation": {
          "$ref": "#/components/schemas/AEPushedAuthorizationRequests.AESponsoredTPPInformation"
        },
        "OnBehalfOf": {
          "$ref": "#/components/schemas/AEOnBehalfOf"
        },
        "PaymentConsumption": {
          "$ref": "#/components/schemas/AEConsentStatus.AEPaymentConsumption"
        },
        "OpenFinanceBilling": {
          "$ref": "#/components/schemas/AEConsentStatus.AEBankServiceInitiationOpenFinanceBilling"
        }
      },
      "required": [
        "ConsentId",
        "ExpirationDateTime",
        "Status",
        "CreationDateTime",
        "StatusUpdateDateTime",
        "ControlParameters",
        "PaymentPurposeCode"
      ],
      "additionalProperties": false
    },
    "Subscription": {
      "$ref": "#/components/schemas/AEStandardModels.AEEventNotification"
    },
    "Links": {
      "$ref": "#/components/schemas/AEConsentStatus.AELinksRelatedPayment"
    },
    "Meta": {
      "$ref": "#/components/schemas/AEConsentStatus.AEMetaMultiAuthorization"
    }
  },
  "description": "Status of the Authorization Request, qualified with additional information held by the API Hub.",
  "additionalProperties": false
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 128,
  "description": "Unique identification assigned by the TPP to identify the consent resource."
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 128,
  "description": "The original ConsentId assigned by the TPP.\n\nIt is used by the TPP for updating/renewing parameters associated with long-lived consents.\nIt must be provided when long-lived consent parameters are updated/renewed for a current consent that has not yet finished."
}

{
  "type": "boolean",
  "description": "Specifies to the LFI that the consent authorization must be completed by a single authorizer at the LFI."
}

{
  "allOf": [
    {
      "$ref": "#/components/schemas/AEDateTime"
    },
    {
      "description": "The date and time by which a Consent (in AwaitingAuthorization status) must be Authorized by the User."
    }
  ]
}

{
  "type": "string",
  "enum": [
    "ReadAccountsBasic",
    "ReadAccountsDetail",
    "ReadBalances",
    "ReadRefundAccount"
  ]
}

{
  "allOf": [
    {
      "$ref": "#/components/schemas/AEDateTime"
    },
    {
      "description": "Specified date and time the consent will expire."
    }
  ]
}

{
  "type": "string",
  "enum": [
    "LFI",
    "TPP",
    "LFI.InitiatedByUser",
    "TPP.InitiatedByUser"
  ],
  "description": "Denotes the Identifier of the revocation.\n\n| Identifier| Description|\n|-----------|------------|\n| LFI | Revoked by LFI without User initiation|\n| TPP | Revoked by TPP without User initiation|\n| LFI.InitiatedByUser | Initiated by User via the LFI|\n| TPP.InitiatedByUser | Initiated by User via the TPP|"
}

{
  "allOf": [
    {
      "$ref": "#/components/schemas/AEDateTime"
    },
    {
      "description": "Date and time at which the Consent was created."
    }
  ]
}

{
  "allOf": [
    {
      "$ref": "#/components/schemas/AEDateTime"
    },
    {
      "description": "Date and time at which the resource status was updated."
    }
  ]
}

{
  "type": "object",
  "required": [
    "ChargeBearer",
    "Type",
    "Amount"
  ],
  "properties": {
    "ChargeBearer": {
      "$ref": "#/components/schemas/AEBankServiceInitiation.AEChargeBearerType1Code"
    },
    "Type": {
      "$ref": "#/components/schemas/AEBankServiceInitiation.AEExternalPaymentChargeTypeCode"
    },
    "Amount": {
      "$ref": "#/components/schemas/AEStandardModels.AEActiveCurrencyAmount"
    }
  },
  "description": "Charges related to the consented payment instruction.",
  "additionalProperties": false
}

{
  "type": "string",
  "enum": [
    "BorneByCreditor",
    "BorneByDebtor",
    "Shared"
  ],
  "description": "Specifies which party/parties will bear the charges associated with the processing of the payment transaction."
}

{
  "type": "string",
  "enum": [
    "VAT",
    "Fees"
  ],
  "description": "Charge type, in a coded form."
}

{
  "type": "object",
  "required": [
    "Amount",
    "Currency"
  ],
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEStandardModels.AEActiveOrHistoricAmount"
    },
    "Currency": {
      "$ref": "#/components/schemas/AEStandardModels.AEActiveOrHistoricCurrencyCode"
    }
  },
  "description": "An Amount qualified by an active Currency.",
  "additionalProperties": false
}

{
  "type": "string",
  "pattern": "^\\d{1,16}\\.\\d{2}$",
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "example": "100.00"
}

{
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'."
}

{
  "type": "object",
  "required": [
    "UnitCurrency",
    "RateType"
  ],
  "properties": {
    "UnitCurrency": {
      "type": "string",
      "pattern": "^[A-Z]{3,3}$",
      "description": "Currency in which the rate of exchange is expressed in a currency exchange. In the example 1GBP = xxxCUR, the unit currency is GBP."
    },
    "ExchangeRate": {
      "type": "number",
      "description": "The factor used for conversion of an amount from one currency to another. This reflects the price at which one currency was bought with another currency."
    },
    "RateType": {
      "$ref": "#/components/schemas/AEBankServiceInitiation.AERateType"
    },
    "ContractIdentification": {
      "type": "string",
      "minLength": 1,
      "maxLength": 256,
      "description": "Unique and unambiguous reference to the foreign exchange contract agreed between the initiating party/creditor and the debtor agent."
    },
    "ExpirationDateTime": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEDateTime"
        },
        {
          "description": "Specified date and time the exchange rate agreement will expire."
        }
      ]
    }
  },
  "description": "Further detailed information on the exchange rate that has been used in the payment transaction - returned by the LFI.",
  "additionalProperties": false
}

{
  "type": "string",
  "enum": [
    "Actual",
    "Agreed",
    "Indicative"
  ],
  "description": "Specifies the type used to complete the currency exchange."
}

{
  "type": "object",
  "required": [
    "ExtendedPurpose",
    "CurrencyOfTransfer"
  ],
  "properties": {
    "InstructionPriority": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEBankServiceInitiation.AEInstructionPriority"
        }
      ],
      "description": "Indicator of the urgency or order of importance that the instructing party would like the instructed party to apply to the processing of the instruction."
    },
    "ExtendedPurpose": {
      "type": "string",
      "minLength": 1,
      "maxLength": 140,
      "description": "Specifies the purpose of an international payment."
    },
    "ChargeBearer": {
      "$ref": "#/components/schemas/AEBankServiceInitiation.AEChargeBearerType1Code"
    },
    "CurrencyOfTransfer": {
      "type": "string",
      "pattern": "^[A-Z]{3,3}$",
      "description": "Specifies the currency of the to be transferred amount, which is different from the currency of the debtor's account."
    },
    "DestinationCountryCode": {
      "type": "string",
      "pattern": "[A-Z]{2,2}",
      "description": "Country in which Credit Account is domiciled. Code to identify a country, a dependency, or another area of particular geopolitical interest, on the basis of country names obtained from the United Nations (ISO 3166, Alpha-2 code)."
    },
    "ExchangeRateInformation": {
      "$ref": "#/components/schemas/AEBankServiceInitiation.AEExchangeRateInformation"
    },
    "FxQuoteId": {
      "type": "string",
      "minLength": 1,
      "maxLength": 128,
      "description": "Required where the consent or payment initiation request relates to a previously quoted FX trade. The TPP must provide the `QuoteId` value where the payment type is a single instant payment, or omit and provide in the payment initiation request where a long-lived consent exists."
    }
  },
  "description": "The details of the non-local currency or FX request that has been agreed between the User and the TPP. The requested ChargeBearer and ExchangeRateInformation included in this object may be superseded by updated information supplied by the LFI.",
  "additionalProperties": false
}

{
  "type": "string",
  "enum": [
    "Normal",
    "Urgent"
  ],
  "description": "Indicator of the urgency or order of importance that the instructing party would like the instructed party to apply to the processing of the instruction."
}

{
  "type": "object",
  "required": [
    "UnitCurrency",
    "RateType"
  ],
  "properties": {
    "UnitCurrency": {
      "type": "string",
      "pattern": "^[A-Z]{3,3}$",
      "description": "Currency in which the rate of exchange is expressed in a currency exchange. In the example 1GBP = xxxCUR, the unit currency is GBP."
    },
    "ExchangeRate": {
      "type": "number",
      "description": "The factor used for conversion of an amount from one currency to another. This reflects the price at which one currency was bought with another currency."
    },
    "RateType": {
      "$ref": "#/components/schemas/AEBankServiceInitiation.AERateType"
    },
    "ContractIdentification": {
      "type": "string",
      "minLength": 1,
      "maxLength": 256,
      "description": "Unique and unambiguous reference to the foreign exchange contract agreed between the initiating party/creditor and the debtor agent."
    }
  },
  "description": "Provides details on the currency exchange rate and contract.",
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "IsDelegatedAuthentication": {
      "type": "boolean",
      "description": "Indicates whether the all payment controls will be defined and managed by the TPP under the Payment with Delegated Authentication capability"
    },
    "ConsentSchedule": {
      "type": "object",
      "properties": {
        "SinglePayment": {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationSingleInstantPayment"
        },
        "MultiPayment": {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationLongLivedPaymentConsent"
        },
        "FilePayment": {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationFilePaymentConsent"
        }
      },
      "description": "The various payment types that can be initiated:\n\n* A Single Payment\n\n* A Multi-Payment\n\n* A Combined Payment (one SinglePayment and one MultiPayment)",
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "Type",
    "Amount"
  ],
  "properties": {
    "Type": {
      "type": "string",
      "enum": [
        "SingleInstantPayment"
      ],
      "description": "The Payment Type"
    },
    "Amount": {
      "$ref": "#/components/schemas/AEStandardModels.AEAmountAndCurrency"
    }
  },
  "description": "A single immediate payment consent that MUST be used for a single payment which will be initiated immediately after User authorization at the LFI.",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "Currency",
    "Amount"
  ],
  "properties": {
    "Currency": {
      "$ref": "#/components/schemas/AEStandardModels.AEActiveOrHistoricCurrencyCode"
    },
    "Amount": {
      "$ref": "#/components/schemas/AEStandardModels.AEActiveOrHistoricAmount"
    }
  },
  "description": "An Amount qualified by Currency",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "PeriodicSchedule"
  ],
  "properties": {
    "MaximumCumulativeValueOfPayments": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEPeriodTypeMaximumCumulativeValueOfPayments"
        }
      ],
      "description": "The maximum cumulative value of all successful payment rails executions under the Consent.\nEach successful payment rails execution amount (related to the Consent) is added to the total cumulative value of the Consent which cannot exceed the maximum value agreed with the User at the point of consent."
    },
    "MaximumCumulativeNumberOfPayments": {
      "type": "integer",
      "description": "The maximum cumulative number of all successful payment rails executions under the Consent.\nEach successful payment rails execution (related to the Consent) is added to the total cumulative number of payments for the Consent which cannot exceed the maximum value agreed with the User at the point of consent.    "
    },
    "PeriodicSchedule": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationLongLivedPaymentConsentPeriodicSchedule"
    }
  },
  "description": "A Consent definition for defining Multi Payments",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "Amount",
    "Currency"
  ],
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEActiveOrHistoricAmount"
    },
    "Currency": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEActiveOrHistoricCurrencyCode"
    }
  },
  "description": "The maximum cumulative payment value of all payment initiations per Period Type.",
  "additionalProperties": false
}

{
  "type": "string",
  "pattern": "^\\d{1,16}\\.\\d{2}$",
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "example": "100.00"
}

{
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'."
}

{
  "oneOf": [
    {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationVariableOnDemand"
    },
    {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationFixedOnDemand"
    },
    {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationVariablePeriodicSchedule"
    },
    {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationFixedPeriodicSchedule"
